import re

KEYS = ['Lines executed', 'Branches executed', 'Taken at least once', 'Calls executed']

def new_row(kind, name):
    r = {'Kind': kind, 'Name': name}
    for k in KEYS:
        r[k] = ''
        r[k + ' total'] = ''
    r['Output'] = ''
    return r

def parse(lines):
    rows = []
    used = []
    summ = {}
    sl = []
    skip = []
    cur = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            cur = None
            continue
        m = re.match(r"^(Function|File) '(.*)'$", s)
        if m:
            cur = new_row(m.group(1), m.group(2))
            rows.append(cur)
            used.append(i)
            continue
        m = re.match(r'^(Lines executed|Branches executed|Taken at least once|Calls executed):\s*([\d.]+%) of (\d+)$', s)
        if m:
            if cur is None:
                summ[m.group(1)] = m.group(2)
                summ[m.group(1) + ' total'] = int(m.group(3))
                sl.append(i)
            else:
                cur[m.group(1)] = m.group(2)
                cur[m.group(1) + ' total'] = int(m.group(3))
                used.append(i)
            continue
        m = re.match(r"^Creating '(.*)'$", s)
        if m:
            if cur is not None:
                cur['Output'] = m.group(1)
                used.append(i)
            else:
                skip.append(i)
            continue
        if re.match(r'^No (calls|branches|executable lines)$', s):
            if cur is not None:
                used.append(i)
            else:
                skip.append(i)
            continue
    blocks = []
    if rows:
        blocks.append({'name': 'coverage', 'kind': 'table', 'lines': used, 'records': rows})
    if summ:
        blocks.append({'name': 'summary', 'kind': 'kv', 'lines': sl, 'records': [summ]})
    return {'blocks': blocks, 'skip': skip}
